    return (StringBuffer('FeedbackCompanion(')
          ..write('id: $id, ')
          ..write('feedbackText: $feedbackText, ')
          ..write('createdAt: $createdAt, ')
          ..write('trainingId: $trainingId')
          ..write(')'))
